import os
from codegen_utils import parse_yaml  # noqa: E402

def generate_go(domains, primitives, modifiers, output_path):
    lines = [
        "// Code generated by generate_fundamental_constants.py. DO NOT EDIT.",
        "package primitives",
        "",
        "import (",
        '\t"errors"',
        '\t"fmt"',
        '\t"math"',
        '\t"sync/atomic"',
        ")",
        "",
        "type ConstantsDomain int",
        "type ConstantsPrimitive int",
        "type ConstantsModifier int",
        "",
        "const ("
    ]
    
    for i in range(10):
        lines.append(f"\tConstantsDomain{domains[i].replace('_', '').capitalize()} ConstantsDomain = {i}")
    lines.append("\n\t// Constants Primitives")
    for i in range(10):
        lines.append(f"\tConstantsPrimitive{primitives[i].replace('_', '').capitalize()} ConstantsPrimitive = {i}")
    lines.append("\n\t// Constants Modifiers")
    for i in range(10):
        lines.append(f"\tConstantsModifier{modifiers[i].replace('_', '').capitalize()} ConstantsModifier = {i}")
    lines.append(")\n")

    lines.extend([
        "func (d ConstantsDomain) String() string {",
        "\tswitch d {"
    ])
    for i in range(10):
        lines.append(f'\tcase {i}: return "{domains[i]}"')
    lines.extend([
        '\tdefault: return "UNKNOWN"',
        "\t}",
        "}",
        "",
        "func (p ConstantsPrimitive) String() string {",
        "\tswitch p {"
    ])
    for i in range(10):
        lines.append(f'\tcase {i}: return "{primitives[i]}"')
    lines.extend([
        '\tdefault: return "UNKNOWN"',
        "\t}",
        "}",
        "",
        "func (m ConstantsModifier) String() string {",
        "\tswitch m {"
    ])
    for i in range(10):
        lines.append(f'\tcase {i}: return "{modifiers[i]}"')
    lines.extend([
        '\tdefault: return "UNKNOWN"',
        "\t}",
        "}",
        "",
        "type ConstantsIdentity struct {",
        "\tDomain    ConstantsDomain",
        "\tPrimitive ConstantsPrimitive",
        "\tModifier  ConstantsModifier",
        "\tCode      uint16",
        "\tName      string",
        "}",
        "",
        "type ConstantsStateVector struct {",
        "\tPlanckScaleRatio        float64",
        "\tGravitationalCoupling   float64",
        "\tElectromagneticShielding float64",
        "\tQuantumEntropy          float64",
        "\tSingularityDensity      float64",
        "\tExecutionCount          uint64",
        "}",
        "",
        "func ResolveConstantsIdentity(d, p, m byte) (ConstantsIdentity, error) {",
        "\tif d > 9 || p > 9 || m > 9 {",
        '\t\treturn ConstantsIdentity{}, errors.New("constants index out of range [0-9]")',
        "\t}",
        "\tcode := uint16(d)*100 + uint16(p)*10 + uint16(m)",
        '\tname := fmt.Sprintf("CONST-%s-%s-%s", ConstantsDomain(d).String(), ConstantsPrimitive(p).String(), ConstantsModifier(m).String())',
        "\treturn ConstantsIdentity{",
        "\t\tDomain:    ConstantsDomain(d),",
        "\t\tPrimitive: ConstantsPrimitive(p),",
        "\t\tModifier:  ConstantsModifier(m),",
        "\t\tCode:      code,",
        "\t\tName:      name,",
        "\t}, nil",
        "}",
        "",
        "type ConstantsHandler func(id ConstantsIdentity, vec *ConstantsStateVector) error",
        "",
        "var (",
        "\tConstantsTable [1000]ConstantsHandler",
        "\tConstantsMetrics [1000]uint64",
        ")",
        "",
        "func InitConstantsKernel() {"
    ])

    for d in range(10):
        for p in range(10):
            for m in range(10):
                code = d*100 + p*10 + m
                domain_str = domains[d]
                prim_str = primitives[p]
                mod_str = modifiers[m]
                lines.append(f"""\tConstantsTable[{code}] = func(id ConstantsIdentity, vec *ConstantsStateVector) error {{
\t\tatomic.AddUint64(&ConstantsMetrics[{code}], 1)
\t\tvec.ExecutionCount++
\t\t// Execute constants simulation step for {domain_str}:{prim_str}:{mod_str}
\t\tvec.PlanckScaleRatio = math.Abs(math.Sin(float64(id.Code))) * 1.616255e-35
\t\tvec.GravitationalCoupling = 6.67430e-11 * (1.0 + 0.01*math.Cos(float64(id.Code)))
\t\tvec.ElectromagneticShielding = 1.602176634e-19 * (float64(id.Code%10) + 1.0)
\t\tvec.QuantumEntropy = math.Max(0.0, vec.QuantumEntropy*0.99 + 1.054571817e-34*float64(id.Code))
\t\tvec.SingularityDensity = vec.GravitationalCoupling / math.Max(1e-100, vec.PlanckScaleRatio*vec.PlanckScaleRatio)
\t\treturn nil
\t}}""")

    lines.extend([
        "}",
        "",
        "func DispatchConstants(d, p, m byte, vec *ConstantsStateVector) error {",
        "\tidentity, err := ResolveConstantsIdentity(d, p, m)",
        "\tif err != nil {",
        "\t\treturn err",
        "\t}",
        "\thandler := ConstantsTable[identity.Code]",
        "\tif handler == nil {",
        '\t\treturn errors.New("constants kernel not initialized")',
        "\t}",
        "\treturn handler(identity, vec)",
        "}",
        "",
        "func GetConstantsExecutionCount(code uint16) uint64 {",
        "\tif code >= 1000 { return 0 }",
        "\treturn atomic.LoadUint64(&ConstantsMetrics[code])",
        "}"
    ])

    os.makedirs(os.path.dirname(output_path), exist_ok=True)
    with open(output_path, 'w') as f:
        f.write('\n'.join(lines))
    print(f"Generated Go constants primitives in {output_path}")

def generate_rust(domains, primitives, modifiers, output_path):
    lines = [
        "// Auto-generated by generate_fundamental_constants.py. DO NOT EDIT.",
        "",
        "#[derive(Debug, Clone, Copy, PartialEq, Eq)]",
        "pub struct ConstantsIdentity {",
        "    pub domain: u8,",
        "    pub primitive: u8,",
        "    pub modifier: u8,",
        "    pub code: u16,",
        "}",
        "",
        "#[derive(Debug, Clone)]",
        "pub struct ConstantsStateVector {",
        "    pub planck_scale_ratio: f64,",
        "    pub gravitational_coupling: f64,",
        "    pub electromagnetic_shielding: f64,",
        "    pub quantum_entropy: f64,",
        "    pub singularity_density: f64,",
        "    pub execution_count: u64,",
        "}",
        "",
        "impl ConstantsStateVector {",
        "    pub fn new() -> Self {",
        "        Self {",
        "            planck_scale_ratio: 1.616255e-35,",
        "            gravitational_coupling: 6.67430e-11,",
        "            electromagnetic_shielding: 1.602176634e-19,",
        "            quantum_entropy: 1.054571817e-34,",
        "            singularity_density: 0.0,",
        "            execution_count: 0,",
        "        }",
        "    }",
        "}",
        "",
        "pub fn dispatch_constants(d: u8, p: u8, m: u8, vec: &mut ConstantsStateVector) -> Result<u16, String> {",
        "    if d > 9 || p > 9 || m > 9 {",
        "        return Err(\"Constants indices out of bounds [0-9]\".to_string());",
        "    }",
        "    let code = (d as u16) * 100 + (p as u16) * 10 + (m as u16);",
        "    vec.execution_count += 1;",
        "    vec.planck_scale_ratio = ((code as f64).sin()).abs() * 1.616255e-35;",
        "    vec.gravitational_coupling = 6.67430e-11 * (1.0 + 0.01 * (code as f64).cos());",
        "    vec.electromagnetic_shielding = 1.602176634e-19 * (((code % 10) as f64) + 1.0);",
        "    vec.quantum_entropy = (vec.quantum_entropy * 0.99 + 1.054571817e-34 * (code as f64)).max(0.0);",
        "    vec.singularity_density = vec.gravitational_coupling / (vec.planck_scale_ratio * vec.planck_scale_ratio).max(1e-100);",
        "    Ok(code)",
        "}"
    ]

    os.makedirs(os.path.dirname(output_path), exist_ok=True)
    with open(output_path, 'w') as f:
        f.write('\n'.join(lines))
    print(f"Generated Rust Constants in {output_path}")

def generate_python(domains, primitives, modifiers, output_path):
    lines = [
        "# Auto-generated by generate_fundamental_constants.py. DO NOT EDIT.",
        "import math",
        "from typing import Tuple",
        "",
        "DOMAINS = " + str(domains),
        "PRIMITIVES = " + str(primitives),
        "MODIFIERS = " + str(modifiers),
        "",
        "class ConstantsStateVector:",
        "    def __init__(self):",
        "        self.planck_scale_ratio = 1.616255e-35",
        "        self.gravitational_coupling = 6.67430e-11",
        "        self.electromagnetic_shielding = 1.602176634e-19",
        "        self.quantum_entropy = 1.054571817e-34",
        "        self.singularity_density = 0.0",
        "        self.execution_count = 0",
        "",
        "def resolve_constants_identity(d: int, p: int, m: int) -> Tuple[int, str]:",
        "    if not (0 <= d <= 9 and 0 <= p <= 9 and 0 <= m <= 9):",
        "        raise ValueError('Index out of range [0-9]')",
        "    code = d * 100 + p * 10 + m",
        "    name = f'CONST-{DOMAINS[d]}-{PRIMITIVES[p]}-{MODIFIERS[m]}'",
        "    return code, name",
        "",
        "def dispatch_constants(d: int, p: int, m: int, vec: ConstantsStateVector) -> Tuple[int, str, float]:",
        "    code, name = resolve_constants_identity(d, p, m)",
        "    vec.execution_count += 1",
        "    vec.planck_scale_ratio = abs(math.sin(code)) * 1.616255e-35",
        "    vec.gravitational_coupling = 6.67430e-11 * (1.0 + 0.01 * math.cos(code))",
        "    vec.electromagnetic_shielding = 1.602176634e-19 * ((code % 10) + 1.0)",
        "    vec.quantum_entropy = max(0.0, vec.quantum_entropy * 0.99 + 1.054571817e-34 * code)",
        "    vec.singularity_density = vec.gravitational_coupling / max(1e-100, vec.planck_scale_ratio ** 2)",
        "    return code, name, vec.singularity_density",
        ""
    ]

    os.makedirs(os.path.dirname(output_path), exist_ok=True)
    with open(output_path, 'w') as f:
        f.write('\n'.join(lines))
    print(f"Generated Python Constants in {output_path}")

def generate_go_test(domains, primitives, modifiers, output_path):
    lines = [
        "// Code generated by generate_fundamental_constants.py. DO NOT EDIT.",
        "package primitives",
        "",
        "import (",
        '\t"testing"',
        ")",
        "",
        "func TestConstantsKernelCoverage(t *testing.T) {",
        "\tInitConstantsKernel()",
        "\tvec := &ConstantsStateVector{PlanckScaleRatio: 1.616255e-35}",
        "\tcount := 0",
        "\tfor d := byte(0); d < 10; d++ {",
        "\t\tfor p := byte(0); p < 10; p++ {",
        "\t\t\tfor m := byte(0); m < 10; m++ {",
        "\t\t\t\terr := DispatchConstants(d, p, m, vec)",
        "\t\t\t\tif err != nil {",
        '\t\t\t\t\tt.Fatalf("Failed to dispatch Constants primitives [%d,%d,%d]: %v", d, p, m, err)',
        "\t\t\t\t}",
        "\t\t\t\tcode := uint16(d)*100 + uint16(p)*10 + uint16(m)",
        "\t\t\t\texecCount := GetConstantsExecutionCount(code)",
        "\t\t\t\tif execCount < 1 {",
        '\t\t\t\t\tt.Errorf("Expected execution count 1 for code %d, got %d", code, execCount)',
        "\t\t\t\t}",
        "\t\t\t\tcount++",
        "\t\t\t}",
        "\t\t}",
        "\t}",
        "\tif count != 1000 {",
        '\t\tt.Fatalf("Expected 1000 Constants primitives tested, got %d", count)',
        "\t}",
        '\tt.Logf("✅ Successfully verified 100%% execution coverage across all 1000 Constants Primitives. Final Quantum Entropy: %e", vec.QuantumEntropy)',
        "}"
    ]

    os.makedirs(os.path.dirname(output_path), exist_ok=True)
    with open(output_path, 'w') as f:
        f.write('\n'.join(lines))
    print(f"Generated Go test suite in {output_path}")

def generate_python_test(domains, primitives, modifiers, output_path):
    lines = [
        "# Auto-generated by generate_fundamental_constants.py. DO NOT EDIT.",
        "import unittest",
        "from cortex.fundamental_constants import dispatch_constants, ConstantsStateVector",
        "",
        "class TestConstantsKernel(unittest.TestCase):",
        "    def test_constants_coverage(self):",
        "        vec = ConstantsStateVector()",
        "        count = 0",
        "        for d in range(10):",
        "            for p in range(10):",
        "                for m in range(10):",
        "                    code, name, density = dispatch_constants(d, p, m, vec)",
        "                    self.assertEqual(code, d*100 + p*10 + m)",
        "                    count += 1",
        "        self.assertEqual(count, 1000)",
        "        print(f'✅ Successfully verified 100% execution coverage for 1000 Python/Constants Primitives. Final Entropy: {vec.quantum_entropy}')",
        "",
        "if __name__ == '__main__':",
        "    unittest.main()",
        ""
    ]

    os.makedirs(os.path.dirname(output_path), exist_ok=True)
    with open(output_path, 'w') as f:
        f.write('\n'.join(lines))
    print(f"Generated Python test suite in {output_path}")

def main():
    yaml_path = "cortex/ontology/fundamental_constants_1000_taxonomy.yaml"
    go_output = "primitives/fundamental_constants.go"
    rust_output = "src-tauri/src/fundamental_constants.rs"
    py_output = "cortex/fundamental_constants.py"
    go_test_output = "primitives/fundamental_constants_test.go"
    py_test_output = "cortex/fundamental_constants_test.py"
    
    domains, primitives, modifiers = parse_yaml(yaml_path)
    generate_go(domains, primitives, modifiers, go_output)
    generate_rust(domains, primitives, modifiers, rust_output)
    generate_python(domains, primitives, modifiers, py_output)
    generate_go_test(domains, primitives, modifiers, go_test_output)
    generate_python_test(domains, primitives, modifiers, py_test_output)

if __name__ == "__main__":
    main()
